import csv
import io
from typing import Iterator

from .errors import LedgerError


def iter_rows(path: str, required: list[str], code: int) -> Iterator[tuple[int, dict[str, str]]]:
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        raise LedgerError(code, f"{path}: cannot read file") from None
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise LedgerError(code, f"{path}: not valid UTF-8") from None

    reader = csv.reader(io.StringIO(text, newline=""))
    try:
        header = next(reader, None)
    except csv.Error:
        raise LedgerError(code, f"{path}: cannot read file") from None
    if not header:
        raise LedgerError(code, f"{path}: missing header")
    names = [h.strip().lower() for h in header]
    seen = set()
    for n in names:
        if n in seen:
            raise LedgerError(code, f"{path}: duplicate column '{n}'")
        seen.add(n)
    for r in required:
        if r not in seen:
            raise LedgerError(code, f"{path}: missing column '{r}'")

    return _rows(path, code, reader, names)


def _rows(path, code, reader, names):
    while True:
        try:
            rec = next(reader, None)
        except csv.Error:
            raise LedgerError(code, f"{path}: cannot read file") from None
        if rec is None:
            return
        if not rec:
            continue
        if len(rec) != len(names):
            raise LedgerError(
                code, f"{path}:{reader.line_num}: expected {len(names)} fields, got {len(rec)}"
            )
        yield reader.line_num, dict(zip(names, rec))

